import mpmath as mp
assert mp.coth(mp.pi/2)<1.1
for N in range(1,7):
    a=N+0.5
    for j in range(-200,201):
        t=a*j/200
        for w in [mp.mpc(a,t),mp.mpc(-a,t)]:
            assert abs(mp.cot(mp.pi*w))<=1+1e-12
        for w in [mp.mpc(t,a),mp.mpc(t,-a)]:
            assert abs(mp.cot(mp.pi*w))<=mp.coth(mp.pi/2)+1e-12
